// Hand smoke test for server.mjs (not shipped). Usage: node smoke.mjs <repoDir>
import { spawn } from 'node:child_process';
import { mkdtempSync, writeFileSync, readFileSync, mkdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';

const repo = process.argv[2];
const tmp = mkdtempSync(join(tmpdir(), 'bk-'));
let failures = 0;
const check = (name, cond, extra = '') => {
  if (!cond) failures++;
  process.stdout.write(`${cond ? 'ok  ' : 'FAIL'} ${name} ${cond ? '' : extra}\n`);
};

function start(env, cwd = tmp) {
  return new Promise((res) => {
    const child = spawn(process.execPath, [join(repo, 'server.mjs')], { cwd, env: { ...process.env, ...env } });
    let out = '', err = '';
    child.stdout.on('data', (d) => { out += d; const m = /:(\d+)\n$/.exec(out); if (m) res({ child, port: Number(m[1]), out: () => out, err: () => err }); });
    child.stderr.on('data', (d) => { err += d; });
    child.on('exit', (code) => res({ code, out, err }));
  });
}

function raw(port, text) {
  return new Promise((res) => {
    const s = net.connect(port, '127.0.0.1', () => s.end(text));
    let data = '';
    s.on('data', (d) => { data += d; });
    s.on('close', () => res(data));
    s.on('error', () => res(data));
  });
}

async function req(port, method, path, { body, type = 'application/json' } = {}) {
  const headers = type ? { 'Content-Type': type } : {};
  const r = await fetch(`http://127.0.0.1:${port}${path}`, { method, headers, body });
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch { json = undefined; }
  return { status: r.status, ct: r.headers.get('content-type'), text, json };
}

